diff --git a/RadixSort/frontier_solution/region_planner.h b/RadixSort/frontier_solution/region_planner.h
new file mode 100644
index 0000000..817c0a9
--- /dev/null
+++ b/RadixSort/frontier_solution/region_planner.h
@@ -0,0 +1,386 @@
+#ifndef _FRONTIER_REGION_PLANNER_INCLUDED
+#define _FRONTIER_REGION_PLANNER_INCLUDED
+
+// Exchange planner behind EdgeListGraph::extractNode2 / consumeTriangle.
+//
+// A misplaced range ("piece") is owned by whichever of its two buckets is
+// processed first: by its destination bucket (an incoming piece) when that
+// bucket comes first, otherwise by the bucket whose interval holds it (an
+// outgoing piece).  The pieces produced by createParallelGraph stay in the
+// retained edge vectors; pieces created by later exchanges are appended to
+// small per-bucket chunk lists.
+//
+// Planning bucket v pairs its incoming pieces with the misplaced slots of
+// its own interval.  Pairs whose displaced elements belong to the incoming
+// piece's bucket are taken first, since both sides land home.  The remaining
+// slots are filled in address order and exchanges that continue each other
+// on both sides are fused.  The pieces the exchanges leave in other
+// buckets' intervals are recorded by consumeTriangle, i.e. after the caller
+// has already started the recursive sort of v.
+
+#include <stdio.h>
+#include <stdlib.h>
+#include <string.h>
+#include <algorithm>
+#include <vector>
+
+namespace frontier_solution {
+
+// One misplaced range: [start, start + len) holds elements of `label` inside
+// the interval of `country`.
+struct Span {
+  sizeT start;
+  sizeT len;
+  int label;
+  int country;
+};
+
+// Piece stored in a chunk list; `other` is the country for incoming pieces
+// and the label for outgoing pieces.
+struct Rec {
+  sizeT start;
+  sizeT len;
+  int other;
+};
+
+static const int kChunkRecs = 10;
+static const int kKeepScratch = 2048;
+struct Chunk {
+  int next;
+  int count;
+  Rec rec[kChunkRecs];
+};
+
+class RegionPlanner {
+ public:
+  Chunk *chunks;
+  int chunkCap;
+  int chunkUsed;
+  int freeChunk;
+  long initialLeft;  // retained-vector pieces not yet planned
+  long liveRecs;     // pieces held in chunk lists
+  int started;
+
+  Span *inBuf, *outBuf;
+  int inCap, outCap;
+  Span *pend;
+  int pendCap, nPend;
+  int *nextBuf;
+  int nextCap;
+
+  const int *rank;
+  int inHead[BUCKETS], inTail[BUCKETS];
+  int outHead[BUCKETS], outTail[BUCKETS];
+
+  RegionPlanner()
+      : chunks(0), chunkCap(0), chunkUsed(0), freeChunk(-1), initialLeft(0), liveRecs(0), started(0),
+        inBuf(0), outBuf(0), inCap(0), outCap(0), pend(0), pendCap(0), nPend(0), nextBuf(0), nextCap(0),
+        rank(0) {}
+  ~RegionPlanner() { releaseAll(); }
+
+  void releaseAll() {
+    free(chunks);
+    free(inBuf);
+    free(outBuf);
+    free(pend);
+    free(nextBuf);
+    chunks = 0;
+    inBuf = outBuf = pend = 0;
+    nextBuf = 0;
+    chunkCap = chunkUsed = 0;
+    inCap = outCap = pendCap = nextCap = 0;
+    freeChunk = -1;
+  }
+
+  static void *grow(void *p, int &cap, int need, size_t elem) {
+    int ncap = need + (need >> 3) + 16;
+    void *np = realloc(p, (size_t)ncap * elem);
+    if (!np) abort();
+    cap = ncap;
+    return np;
+  }
+
+  void start(std::vector<Edge> *toEdges, std::vector<Edge> *fromEdges, const int *rank_) {
+    started = 1;
+    rank = rank_;
+    long total = 0;
+    for (int b = 0; b < BUCKETS; b++) {
+      total += (long)toEdges[b].size() + (long)fromEdges[b].size();
+      inHead[b] = inTail[b] = outHead[b] = outTail[b] = -1;
+    }
+    initialLeft = total;
+  }
+
+  inline int newChunk() {
+    int c = freeChunk;
+    if (c >= 0) {
+      freeChunk = chunks[c].next;
+    } else {
+      if (chunkUsed == chunkCap) {
+        int ncap = chunkCap ? chunkCap * 2 : 64;
+        Chunk *nc = (Chunk *)realloc(chunks, (size_t)ncap * sizeof(Chunk));
+        if (!nc) abort();
+        chunks = nc;
+        chunkCap = ncap;
+      }
+      c = chunkUsed++;
+    }
+    chunks[c].next = -1;
+    chunks[c].count = 0;
+    return c;
+  }
+
+  inline void append(int *head, int *tail, int b, sizeT s, sizeT l, int other) {
+    int t = tail[b];
+    if (t < 0 || chunks[t].count == kChunkRecs) {
+      int c = newChunk();
+      if (t < 0) head[b] = c; else chunks[t].next = c;
+      tail[b] = c;
+      t = c;
+    }
+    Chunk &C = chunks[t];
+    Rec &R = C.rec[C.count++];
+    R.start = s;
+    R.len = l;
+    R.other = other;
+  }
+
+  // Moves the chunk list of bucket b into dst (as spans) and frees its chunks.
+  inline int drain(int *head, int *tail, int b, Span *dst, bool incoming, int v) {
+    int n = 0;
+    int c = head[b];
+    while (c >= 0) {
+      Chunk &C = chunks[c];
+      for (int i = 0; i < C.count; i++) {
+        dst[n].start = C.rec[i].start;
+        dst[n].len = C.rec[i].len;
+        if (incoming) {
+          dst[n].country = C.rec[i].other;
+          dst[n].label = v;
+        } else {
+          dst[n].label = C.rec[i].other;
+          dst[n].country = v;
+        }
+        n++;
+      }
+      int nx = C.next;
+      C.next = freeChunk;
+      freeChunk = c;
+      c = nx;
+    }
+    head[b] = tail[b] = -1;
+    return n;
+  }
+
+  inline int listCount(const int *head, int b) const {
+    int n = 0;
+    for (int c = head[b]; c >= 0; c = chunks[c].next) n += chunks[c].count;
+    return n;
+  }
+
+  // Records the pieces left behind by the last planned node.
+  void applyPending() {
+    for (int i = 0; i < nPend; i++) {
+      const Span &P = pend[i];
+      int x = P.country, y = P.label;
+      if (rank[y] < rank[x]) append(inHead, inTail, y, P.start, P.len, x);
+      else append(outHead, outTail, x, P.start, P.len, y);
+    }
+    liveRecs += nPend;
+    nPend = 0;
+    if (initialLeft == 0 && liveRecs == 0) releaseAll();
+  }
+
+  static inline int emit(Triangle *tri, int count, sizeT o1, sizeT o2, sizeT a, int from, int to) {
+    if (count > 0) {
+      Triangle &L = tri[count - 1];
+      if (L.offset1 + L.amount == o1 && L.offset2 + L.amount == o2) {
+        L.amount += a;
+        return count;
+      }
+    }
+    Triangle &T = tri[count];
+    T.from = from;
+    T.to = to;
+    T.offset1 = o1;
+    T.offset2 = o2;
+    T.amount = a;
+    return count + 1;
+  }
+
+  static void sortByStart(Span *a, int n) {
+    if (n < 24) {
+      for (int i = 1; i < n; i++) {
+        Span x = a[i];
+        int j = i - 1;
+        while (j >= 0 && a[j].start > x.start) {
+          a[j + 1] = a[j];
+          j--;
+        }
+        a[j + 1] = x;
+      }
+    } else {
+      std::sort(a, a + n, [](const Span &l, const Span &r) { return l.start < r.start; });
+    }
+  }
+
+  int plan(int v, Triangle *tri, std::vector<Edge> &toEdges, std::vector<Edge> &fromEdges) {
+    if (nPend) applyPending();
+    const int nInit = (int)toEdges.size(), nOutInit = (int)fromEdges.size();
+    const int nInNew = inHead[v] >= 0 ? listCount(inHead, v) : 0;
+    const int nOutNew = outHead[v] >= 0 ? listCount(outHead, v) : 0;
+    const int nIn = nInit + nInNew, nOut = nOutInit + nOutNew;
+    initialLeft -= nInit + nOutInit;
+    liveRecs -= nInNew + nOutNew;
+    if (nIn == 0 && nOut == 0) return 0;
+    if (nIn > inCap) inBuf = (Span *)grow(inBuf, inCap, nIn, sizeof(Span));
+    if (nIn > nextCap) nextBuf = (int *)grow(nextBuf, nextCap, nIn, sizeof(int));
+    if (nOut + nOutNew > outCap) outBuf = (Span *)grow(outBuf, outCap, nOut + nOutNew, sizeof(Span));
+
+    // Outgoing pieces in address order: the retained vector is sorted, the
+    // appended pieces are sorted here and merged in.
+    Span *out = outBuf;
+    if (nOutNew == 0) {
+      const Edge *e = fromEdges.data();
+      for (int i = 0; i < nOutInit; i++) {
+        out[i].start = e[i].start;
+        out[i].len = e[i].amount;
+        out[i].label = e[i].to;
+        out[i].country = v;
+      }
+    } else {
+      Span *tmp = outBuf + nOut;
+      drain(outHead, outTail, v, tmp, false, v);
+      sortByStart(tmp, nOutNew);
+      const Edge *e = fromEdges.data();
+      int i = 0, j = 0, k = 0;
+      while (i < nOutInit && j < nOutNew) {
+        if (e[i].start < tmp[j].start) {
+          out[k].start = e[i].start;
+          out[k].len = e[i].amount;
+          out[k].label = e[i].to;
+          out[k].country = v;
+          i++;
+        } else {
+          out[k] = tmp[j++];
+        }
+        k++;
+      }
+      for (; i < nOutInit; i++, k++) {
+        out[k].start = e[i].start;
+        out[k].len = e[i].amount;
+        out[k].label = e[i].to;
+        out[k].country = v;
+      }
+      for (; j < nOutNew; j++, k++) out[k] = tmp[j];
+    }
+
+    // Incoming pieces grouped by the country holding them.
+    Span *in = inBuf;
+    {
+      const Edge *e = toEdges.data();
+      for (int i = 0; i < nInit; i++) {
+        in[i].start = e[i].start;
+        in[i].len = e[i].amount;
+        in[i].country = e[i].from;
+        in[i].label = v;
+      }
+      if (nInNew) drain(inHead, inTail, v, in + nInit, true, v);
+    }
+
+    int count = 0;
+#ifndef FRONTIER_NO_2CYCLES
+    {
+      // first/next links of incoming pieces per country (only touched ones)
+      int first[BUCKETS];
+      unsigned char seen[BUCKETS];
+      memset(seen, 0, sizeof(seen));
+      int *nextIn = nextBuf;
+      for (int i = nIn - 1; i >= 0; i--) {
+        int c = in[i].country;
+        nextIn[i] = seen[c] ? first[c] : -1;
+        first[c] = i;
+        seen[c] = 1;
+      }
+      for (int k = 0; k < nOut; k++) {
+        int y = out[k].label;
+        if (!seen[y]) continue;
+        int i = first[y];
+        Span &Q = out[k];
+        while (i >= 0) {
+          Span &P = in[i];
+          sizeT a = P.len < Q.len ? P.len : Q.len;
+          count = emit(tri, count, P.start, Q.start, a, y, y);
+          P.start += a;
+          P.len -= a;
+          Q.start += a;
+          Q.len -= a;
+          if (P.len == 0) i = nextIn[i];
+          if (Q.len == 0) break;
+        }
+        if (i < 0) seen[y] = 0; else first[y] = i;
+      }
+    }
+#endif
+
+    // Fill the remaining slots of v in address order.
+    {
+      int rem = 0;
+      for (int t = 0; t < nIn; t++) rem += in[t].len != 0;
+      for (int t = 0; t < nOut; t++) rem += out[t].len != 0;
+      if (rem > pendCap) pend = (Span *)grow(pend, pendCap, rem, sizeof(Span));
+    }
+    int np = 0;
+    int i = 0, k = 0;
+    while (i < nIn && in[i].len == 0) i++;
+    while (k < nOut && out[k].len == 0) k++;
+    while (i < nIn && k < nOut) {
+      Span &P = in[i];
+      Span &Q = out[k];
+      sizeT a = P.len < Q.len ? P.len : Q.len;
+      int x = P.country, y = Q.label;
+      count = emit(tri, count, P.start, Q.start, a, x, y);
+      if (x != y) {
+        if (np > 0 && pend[np - 1].country == x && pend[np - 1].label == y &&
+            pend[np - 1].start + pend[np - 1].len == P.start) {
+          pend[np - 1].len += a;
+        } else {
+          Span &N = pend[np++];
+          N.start = P.start;
+          N.len = a;
+          N.label = y;
+          N.country = x;
+        }
+      }
+      P.start += a;
+      P.len -= a;
+      Q.start += a;
+      Q.len -= a;
+      if (P.len == 0) {
+        do i++; while (i < nIn && in[i].len == 0);
+      }
+      if (Q.len == 0) {
+        do k++; while (k < nOut && out[k].len == 0);
+      }
+    }
+#ifdef FRONTIER_DEBUG
+    if (i < nIn || k < nOut) {
+      fprintf(stderr, "planner: unbalanced node %d\n", v);
+      abort();
+    }
+#endif
+    nPend = np;
+    if (np == 0 && initialLeft == 0 && liveRecs == 0) {
+      releaseAll();
+    } else {
+      // do not keep the scratch of an exceptionally large node alive
+      if (inCap > kKeepScratch) { free(inBuf); inBuf = 0; inCap = 0; free(nextBuf); nextBuf = 0; nextCap = 0; }
+      if (outCap > kKeepScratch) { free(outBuf); outBuf = 0; outCap = 0; }
+    }
+    return count;
+  }
+};
+
+}  // namespace frontier_solution
+
+#endif
